package com.wattracker.android.cloud

import com.wattracker.android.json.optArray
import com.wattracker.android.json.optBoolean
import com.wattracker.android.json.optDouble
import com.wattracker.android.json.optInt
import com.wattracker.android.json.optString
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * The #410 removal rule against the shared vector, unmodified.
 *
 * `tests/vectors/removal_decision_v1.json` is generated by
 * `scripts/generate_behaviour_vectors.py` and read, unmodified, by the Python
 * suite (`tests/test_behaviour_vectors.py`), the Swift suite
 * (`BehaviourVectorTests.testEveryRemovalDecisionVectorMatches`) and this
 * file, so the three clients are checked against the same rule rather than
 * against three transcriptions of it.
 *
 * The header goes through [parseHttpDate], the same parser the transport
 * uses, so "unparseable means absent" is checked end to end: an obsolete
 * RFC 850 date or an asctime string is not a date this client will act on.
 */
class RemovalDecisionVectorTest {

    @Test
    fun theSessionToleranceMatchesTheVector() {
        val file = TestVectors.parse("removal_decision_v1.json")
        val tolerance = file.optDouble("clock_skew_tolerance_seconds")
            ?: throw AssertionError("vector has no clock_skew_tolerance_seconds")
        assertEquals(CloudSession.clockSkewTolerance, tolerance, 1e-9)
    }

    @Test
    fun everyRemovalDecisionVectorMatches() {
        val file = TestVectors.parse("removal_decision_v1.json")
        val nowMillis = (file.optInt("now_epoch") ?: 0) * 1000L
        val cases = file.optArray("cases")
            ?: throw AssertionError("vector has no cases")
        // Asserted before the loop: a vector that came out empty or
        // truncated would otherwise pass by checking nothing. Regenerate the
        // vector and move this number on purpose, with the rule it covers.
        assertEquals("removal_decision_v1.json case count", 23, cases.size)

        for (entry in cases) {
            val name = entry.optString("name")
                ?: throw AssertionError("case has no name")
            val status = entry.optInt("status")
            val rawHeader = entry.optString("date_header_raw")
            val offsetSeconds = entry.optDouble("date_offset_seconds")
            val expected = entry.optBoolean("complete_locally")
                ?: throw AssertionError("case $name has no complete_locally")

            val serverDateMillis = rawHeader?.let { parseHttpDate(it) }
            // The vector's offset is what the header encodes relative to
            // `now_epoch`: null when it encodes nothing usable. The parser
            // must agree, or the rule below is not what the transport does.
            if (offsetSeconds != null) {
                assertEquals(name, nowMillis + (offsetSeconds * 1000).toLong(), serverDateMillis)
            } else {
                assertNull(name, serverDateMillis)
            }

            assertEquals(
                name,
                expected,
                CloudSession.removalCompletesLocally(status, serverDateMillis, nowMillis),
            )
        }
    }
}
